#include <bits/stdc++.h>
using namespace std;
int main(){
    int n; cin >> n;
    vector<long long> a(n);
    for (auto &x : a) cin >> x;
    long long mx = *max_element(a.begin(), a.end());
    bool firstWins;
    if (mx >= 2) {
        long long x = 0;
        for (auto v : a) x ^= v;
        firstWins = (x != 0);
    } else {
        int ones = 0;
        for (auto v : a) if (v == 1) ones++;
        firstWins = (ones % 2 == 0);
    }
    cout << (firstWins ? "First" : "Second") << "\n";
}

#include <bits/stdc++.h>
using namespace std;
int main(){
    const int MAXN = 1000;
    vector<int> g(MAXN + 1, 0);
    for (int n = 1; n <= MAXN; n++) {
        set<int> reachable;
        for (int a = 1; a < n - a; a++) { // a < b = n-a ensures a != b, avoids dup
            int b = n - a;
            reachable.insert(g[a] ^ g[b]);
        }
        int mex = 0;
        while (reachable.count(mex)) mex++;
        g[n] = mex;
    }
    int m; cin >> m;
    int x = 0;
    for (int i = 0; i < m; i++) { int v; cin >> v; x ^= g[v]; }
    cout << (x != 0 ? "First" : "Second") << "\n";
}

#include <bits/stdc++.h>
using namespace std;
int main(){
    const int MAXN = 1000;
    vector<int> S = {1, 3, 4};
    vector<int> g(MAXN + 1, 0);
    for (int n = 1; n <= MAXN; n++) {
        set<int> reach;
        for (int s : S) if (s <= n) reach.insert(g[n - s]);
        int mex = 0;
        while (reach.count(mex)) mex++;
        g[n] = mex;
    }
    int m; cin >> m;
    int x = 0;
    for (int i = 0; i < m; i++) { int v; cin >> v; x ^= g[v]; }
    cout << (x != 0 ? "First" : "Second") << "\n";
}

#include <bits/stdc++.h>
using namespace std;
int main(){
    const int MAXN = 1000;
    vector<int> gB(MAXN + 1, 0);
    vector<int> Sb = {1, 3, 4};
    for (int n = 1; n <= MAXN; n++) {
        set<int> reach;
        for (int s : Sb) if (s <= n) reach.insert(gB[n - s]);
        int mex = 0;
        while (reach.count(mex)) mex++;
        gB[n] = mex;
    }
    int m; cin >> m;
    int x = 0;
    for (int i = 0; i < m; i++) {
        char t; int v; cin >> t >> v;
        int gv;
        if (t == 'A') gv = v % 3;
        else if (t == 'B') gv = gB[v];
        else gv = v; // type C: standard Nim pile, Grundy(v) = v
        x ^= gv;
    }
    cout << (x != 0 ? "First" : "Second") << "\n";
}
